#include <bits/stdc++.h>
using namespace std;

int dfs(int tv, int tk, int ts, int last, vector<vector<vector<int>>> &dp, const vector<vector<int>> &freq, const vector<vector<int>> &pos) {
    int cv = freq.size() - 1;
    int ck = freq[0].size() - 1;
    int cs = freq[0].size() - 1;
    if (tv == cv && tk == ck && ts == cs) return 0;
    if (dp[tv][tk][ts] != -1) return dp[tv][tk][ts];
    int result = INT_MAX / 2;
    if (tv < cv) {
        int p = pos[0][tv];
        int move = max(freq[p][0] - tv, 0) + max(freq[p][1] - tk, 0) + max(freq[p][2] - ts, 0) - 1;
        result = min(result, dfs(tv + 1, tk, ts, 0, dp, freq, pos) + move);
    }
    if (tk < ck && last != 0) {
        int p = pos[1][tk];
        int move = max(freq[p][0] - tv, 0) + max(freq[p][1] - tk, 0) + max(freq[p][2] - ts, 0) - 1;
        result = min(result, dfs(tv, tk + 1, ts, 1, dp, freq, pos) + move);
    }
    if (ts < cs) {
        int p = pos[2][ts];
        int move = max(freq[p][0] - tv, 0) + max(freq[p][1] - tk, 0) + max(freq[p][2] - ts, 0) - 1;
        result = min(result, dfs(tv, tk, ts + 1, 2, dp, freq, pos) + move);
    }
    return dp[tv][tk][ts] = result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string cStr;
    cin >> cStr;
    vector<char> c(cStr.begin(), cStr.end());

    int cv = 0, ck = 0, cs = 0;
    vector<vector<int>> freq(n + 1, vector<int>(3, 0));
    vector<vector<int>> pos(3);
    for (int i = 0; i < 3; i++) pos[i] = vector<int>();
    int idx = 0;
    for (char x : c) {
        for (int i = 0; i <= n; i++) {
            if (i > 0) {
                freq[i][0] = freq[i - 1][0];
                freq[i][1] = freq[i - 1][1];
                freq[i][2] = freq[i - 1][2];
            }
        }
        if (x == 'V') {
            freq[idx + 1][0]++;
            cv++;
            pos[0].push_back(idx + 1);
        } else if (x == 'K') {
            freq[idx + 1][1]++;
            ck++;
            pos[1].push_back(idx + 1);
        } else {
            freq[idx + 1][2]++;
            cs++;
            pos[2].push_back(idx + 1);
        }
        idx++;
    }

    vector<vector<vector<int>>> dp(cv + 1, vector<vector<int>>(ck + 1, vector<int>(cs + 1, -1)));
    cout << dfs(cv, ck, cs, 2, dp, freq, pos) << "\n";

    return 0;
}

